#include <iostream>
#include <memory>
struct Node {
    std::weak_ptr<Node> parent;
};
int main() {
    auto root = std::make_shared<Node>();
    auto child = std::make_shared<Node>();
    child->parent = root;
    {
        auto observed = child->parent.lock();
        std::cout << bool(observed) << ' ';
    }
    root.reset();
    std::cout << child->parent.expired() << '\n';
}

